cost_a = [0, 4, 10]
cost_b = [0, 2, 5, 12]
limit = 10
options = []
for a in range(len(cost_a)):
    for b in range(len(cost_b)):
        spent = cost_a[a] + cost_b[b]
        if spent <= limit:
            options.append((a + b, a, limit - spent))
print(max(options))
